            measured = measurement[measured_key]
            if measured > limit:
                run.add(
                    "budgets",
                    "BUDGET_EXCEEDED",
                    "error",
                    f"vault/{file_key}.md",
                    f"{file_key}.{measured_key} is {measured}, above the configured limit {threshold_key}={limit}",
                )


